async function main(ctx) {
  const input = ctx.input || {};
  const url = String(input.url || '').trim();
  if (!url) throw new Error('url is required');
  let parsed;
  try { parsed = new URL(url); } catch (e) { throw new Error('url must be a valid absolute http(s) URL'); }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') throw new Error('url must start with http:// or https://');

  const rawType = String(input.responseType || 'json').trim().toLowerCase();
  const mapped = rawType === 'binary' ? 'base64' : rawType;
  const allowed = ['json','text','base64'];
  if (!allowed.includes(mapped)) {
    throw new Error('responseType must be one of: json, text, base64, binary');
  }

  const headers = (input.headers && typeof input.headers === 'object' && !Array.isArray(input.headers)) ? input.headers : undefined;

  return { url: parsed.toString(), responseType: mapped, headers };
}
